sed -i 's@src={project.thumbnailUrl || project.url}@src={project.series.toLowerCase() === "logomarcas" ? `/logo-${project.title.split("—")[0].trim().toLowerCase().normalize("NFD").replace(/[\\u0300-\\u036f]/g, "").replace(/\\s+/g, "-").replace(/[^a-z0-9-]/g, "")}.png` : (project.thumbnailUrl || project.url)} onError={(e) => { (e.target as HTMLImageElement).style.opacity = "0"; }}@g' src/components/IndexGrid.tsx
